MATCH (loop:ProcessInstrumentationFunction {loop_tag: 'LSHH-164004'})-[:send_signal_to*1..]->(actuator:PlantItem {kind: 'actuator'})-[:control]->(valve:Valve)
RETURN DISTINCT valve.tag AS tag
ORDER BY tag;

MATCH (:PlantItem {tag: 'E-18302'})-[:is_drawn_on]->(s:Sheet)
RETURN s.sheet_id AS sheet_id
ORDER BY sheet_id;

MATCH (a:PlantItem {tag: 'H-9301'}), (b:PlantItem {tag: 'E-9301'}), (r:PlantItem {tag: 'R-9301'})
WHERE EXISTS {
  MATCH (a) ((x)-[:line_to]->(y) WHERE y <> r)+ (b)
}
RETURN a.tag AS from_tag, b.tag AS to_tag

MATCH (item:PlantItem {tag: 'M-16501'})-[:is_drawn_on]->(sheet:Sheet)
RETURN DISTINCT sheet.sheet_id AS sheet_id
ORDER BY sheet_id;

MATCH (a:PlantItem {tag: 'P-7202'}), (b:PlantItem {tag: 'D-7201'})
RETURN a.tag AS source_tag, b.tag AS destination_tag,
       EXISTS {
         MATCH (a) ((x)-[:line_to]->(y) WHERE y.tag <> 'CHV-72005')+ (b)
       } AS reachable_without_CHV-72005

MATCH (a:PlantItem {tag: 'TK-18504'}), (b:PlantItem {tag: 'P-18501A'}), (v:Valve)
WHERE EXISTS { (a)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*0..]->(b) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag;

