MATCH (a:PlantItem {tag: 'V-10201'}), (b:PlantItem {tag: 'P-10302'})
RETURN a.tag AS source_tag, b.tag AS target_tag,
       EXISTS {
         MATCH p = shortestPath((a)-[:line_to*]->(b))
         WHERE NONE(n IN nodes(p) WHERE n.tag = 'P-10201')
       } AS reachable_without_P_10201;

